using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EurekaAction", menuName = "Data/Battle/Battle Actions/Moonie/Eureka Action")]
public class EurekaAction : ConvertAction
{
	[SerializeField]
	private PlayerDiceInventoryData allDicePool;

	protected override void ConvertFirstSecondAction(DiceInstance diceInstance, bool firstAction, bool secondAction)
	{
		Dice dice = diceInstance.OriginalDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
		ChangeDieFace(diceInstance.ActionFace);
		ChangeDieFace(dice.GetDiceFaces()[diceInstance.RolledDiceFaceIndex]);
		allDicePool.DiceForged(diceInstance, dice);
		void ChangeDieFace(ActionFace actionFace)
		{
			if (firstAction)
			{
				actionFace.SetActionModifierLock(isLocked: false);
				actionFace.TurnActionValueIntoModifiedActionValueAndReset();
				actionFace.BattleAction = GetConvertedBattleAction(actionFace.BattleAction);
			}
			if (secondAction)
			{
				actionFace.SetSecondActionModifierLock(isLocked: false);
				actionFace.TurnSecondActionValueIntoModifiedActionValueAndReset();
				actionFace.SecondBattleAction = GetConvertedBattleAction(diceInstance.ActionFace.SecondBattleAction);
			}
			actionFace.KeepChanges = true;
			actionFace.NewBattleAction = actionFace.BattleAction;
			actionFace.NewActionValue = actionFace.ActionValue;
			actionFace.NewSecondBattleAction = actionFace.SecondBattleAction;
			actionFace.NewSecondActionValue = actionFace.SecondActionValue;
		}
	}
}
